def dominant_run(frame_idxs, blobs, max_gap=2):
    """Pick the athlete track among contiguous detection runs.

    The athlete moves smoothly across the frame (a nearly straight, monotonic
    horizontal path), whereas background/compression noise produces blobs that
    jump around erratically. Score each run by its horizontal straightness
    (net displacement / path length) weighted by length, so a long, coherent
    trajectory beats large but incoherent noise blobs."""
    if not frame_idxs:
        return []
    runs = []
    cur = [frame_idxs[0]]
    for a, b in zip(frame_idxs, frame_idxs[1:]):
        if b - a <= max_gap:
            cur.append(b)
        else:
            runs.append(cur)
            cur = [b]
    runs.append(cur)

    def score(run):
        if len(run) < 3:
            return -1.0
        cxs = np.array([blobs[i][0] for i in run])
        steps = np.abs(np.diff(cxs))
        path = steps.sum()
        net = abs(cxs[-1] - cxs[0])
        straight = net / (path + 1e-6)
        return straight * len(run)

    return max(runs, key=score)
